            la=arr.get(a)
            if not la: continue
            j=len(la)-1
            while j>=0 and la[j]>t: j-=1
            if j<0: continue
            ok = (la[j]>=t-delta) or (a==src and free_start and la[j]==-10**9)
            if ok:
                lb=arr[b]
                if not lb or lb[-1]!=t:
                    lb.append(t); pred[(b,t)]=(a,la[j])
    if not arr.get(dst) or arr[dst][0]==-10**9: return None,None
    tt=arr[dst][0]; path=[]; cur=(dst,tt)
